<?php
require __DIR__.'/app-bootstrap.php';$u=require_login();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$action=(string)($_POST['action']??'');if($action==='revoke'){$id=(int)($_POST['session_id']??0);$pdo->prepare('UPDATE user_sessions SET revoked_at=NOW() WHERE id=? AND user_id=?')->execute([$id,(int)$u['id']]);$message='Session revoked.';}elseif($action==='password'){ $password=(string)($_POST['password']??'');if(strlen($password)<12)throw new RuntimeException('Use at least 12 characters.');$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),(int)$u['id']]);$message='Password updated.';}elseif($action==='email'){ $email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');$st=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?');$st->execute([$email,(int)$u['id']]);if($st->fetch())throw new RuntimeException('That email address is already in use.');$token=security_token();$pdo->prepare('DELETE FROM email_change_requests WHERE user_id=?')->execute([(int)$u['id']]);$pdo->prepare('INSERT INTO email_change_requests(user_id,new_email,token_hash,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))')->execute([(int)$u['id'],$email,security_token_hash($token)]);send_store_mail($email,'Confirm your email change','Confirm this change within one hour: '.url('confirm-email.php?token='.rawurlencode($token)));$message='A confirmation link has been sent to the new address.';}else throw new RuntimeException('Unknown security action.');}catch(Throwable $e){$error=$e->getMessage();}}
$st=$pdo->prepare('SELECT id,created_at,last_seen_at,ip_address,user_agent FROM user_sessions WHERE user_id=? AND revoked_at IS NULL ORDER BY last_seen_at DESC');$st->execute([(int)$u['id']]);$sessions=$st->fetchAll();layout_header('Account security');?><div class="section-title"><div><span class="kicker">ACCOUNT</span><h1>Security</h1></div></div><?php if($message):?><div class="panel success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="panel error"><?=e($error)?></div><?php endif;?><div class="security-grid"><section class="panel"><h2>Password</h2><p class="muted">Set a password for account recovery and administrator access.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><label>New password<input type="password" name="password" minlength="12" autocomplete="new-password" required></label><button class="button">Change password</button></form></section><section class="panel"><h2>Change email</h2><p class="muted">The new address must be confirmed before it replaces your current email.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="email"><label>New email address<input type="email" name="email" autocomplete="email" required></label><button class="button">Send confirmation</button></form></section></div><section class="panel"><h2>Active sessions</h2><div class="admin-table"><?php foreach($sessions as $session):?><div class="admin-row"><span><strong><?=e($session['user_agent']?:'Unknown browser')?></strong><small>Last active <?=e($session['last_seen_at'])?></small></span><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="revoke"><input type="hidden" name="session_id" value="<?=$session['id']?>"><button class="button tiny secondary">Revoke</button></form></div><?php endforeach;?></div></section><?php layout_footer();
